@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap');
:root{--ink:#172432;--muted:#758291;--paper:#f5f6f2;--white:#fff;--line:#e6e9e3;--green:#73d39a;--green-deep:#298b59;--lime:#c8f36d;--nav:#111d2a;--nav2:#1b2938;--orange:#f2a05c;--red:#e87575;--blue:#85b9eb;--shadow:0 10px 24px #1724320c}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'Space Grotesk',sans-serif;font-size:14px}button{font:inherit;cursor:pointer}.game-shell{min-height:100vh;display:flex}.sidebar{width:242px;background:var(--nav);color:#eaf0f0;padding:24px 15px 15px;display:flex;flex-direction:column;flex-shrink:0;min-height:100vh}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#fff;padding:0 8px 26px}.brand-mark{width:35px;height:35px;background:var(--lime);color:#172432;display:grid;place-items:center;font-weight:700;letter-spacing:-2px;font-size:12px;box-shadow:3px 3px 0 #83a845}.brand-mark span{color:#368a54}.brand-name{font-size:12px;letter-spacing:1.6px;font-weight:700;line-height:1.1}.brand-name span{display:block;color:#9eabb7;font-size:8px;letter-spacing:2px;margin-top:5px}.club-mini{border:1px solid #ffffff19;background:#ffffff08;padding:11px 9px;display:flex;gap:10px;align-items:center;border-radius:4px;margin-bottom:26px;position:relative}.club-mini b{font-size:10px;letter-spacing:.55px;display:block}.club-mini small{font-size:10px;color:#99a7b3;display:block;margin-top:4px}.crest{position:relative;background:#b9ef70;color:#16382b;display:grid;place-items:center;clip-path:polygon(0 0,100% 0,100% 72%,50% 100%,0 72%);font-size:22px;text-shadow:1px 1px #fff}.crest-small{width:36px;height:42px}.online-dot,.season-dot{width:7px;height:7px;background:#6cdd9b;border-radius:50%;display:block}.online-dot{margin-left:auto;align-self:flex-start;box-shadow:0 0 8px #6cdd9b}.nav-label{font-size:9px;color:#748493;font-weight:700;letter-spacing:1.5px;padding:0 10px 10px}.main-nav{display:grid;gap:4px}.nav-item{border:0;background:transparent;color:#9eabb7;text-align:left;padding:11px 10px;border-radius:4px;font-size:12px;display:flex;align-items:center;gap:12px;transition:.18s}.nav-item:hover{background:#ffffff0b;color:#fff}.nav-item.active{color:#e9ffce;background:#a5e96918;box-shadow:inset 3px 0 var(--lime)}.nav-icon{font-size:17px;width:18px;text-align:center;color:#8da0ad}.active .nav-icon{color:var(--lime)}.nav-count{margin-left:auto;background:#ffffff14;padding:2px 6px;border-radius:3px;font:10px 'DM Mono',monospace}.nav-arrow{margin-left:auto;font-size:17px}.sidebar-bottom{margin-top:auto}.season-card{background:#1b2b39;border:1px solid #ffffff12;padding:13px;border-radius:4px;margin:12px 0 16px}.season-head{font:9px 'DM Mono',monospace;color:#9caebb;letter-spacing:.6px;display:flex;gap:7px;align-items:center}.season-dot{background:var(--lime);width:6px;height:6px}.season-name{font-weight:700;margin:10px 0 11px;font-size:13px}.season-progress{height:4px;background:#ffffff16;border-radius:6px;margin-bottom:8px}.season-progress i{height:100%;width:44%;background:var(--lime);display:block}.season-card small{font:9px 'DM Mono',monospace;color:#93a2af}.season-card small b{color:#eff5f5}.help-link{color:#aab7bf;border:0;background:none;font-size:11px;padding:5px 8px 15px;display:flex;gap:8px}.profile{border-top:1px solid #ffffff16;padding:15px 2px 3px;display:flex;align-items:center;gap:9px}.avatar{display:grid;place-items:center;border-radius:4px}.manager-avatar{background:#f2b976;color:#593f2b;width:33px;height:33px;font-size:17px}.profile b{font-size:11px;display:block}.profile small{color:#8e9ba8;font-size:9px;display:block;margin-top:4px}.profile button{margin-left:auto;background:transparent;color:#aab7bf;border:0;font-size:17px}.main-area{flex:1;min-width:0;display:flex;flex-direction:column}.topbar{height:65px;border-bottom:1px solid #e6e9e4;background:#ffffffb8;display:flex;align-items:center;justify-content:space-between;padding:0 34px}.breadcrumb{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#9aa3a9}.breadcrumb i{font-style:normal;margin:0 10px;color:#c5cbc9}.breadcrumb b{color:#3a4955;font-weight:500}.top-actions{display:flex;align-items:center;gap:21px}.season-pill{font:10px 'DM Mono',monospace;color:#687680}.season-pill span{font-size:14px;margin-right:5px}.season-pill b{background:#e8f7dc;color:#438655;padding:5px 7px;margin-left:8px;border-radius:3px}.weather{font-size:11px;color:#53616b;border-left:1px solid var(--line);padding-left:18px}.weather span{color:#f5b64f;font-size:15px}.weather small{color:#9ba5ab;margin-left:4px}.icon-btn{border:0;background:none;color:#667580;font-size:17px}.top-avatar{width:29px;height:29px;font-size:15px}.content{max-width:1410px;width:100%;margin:0 auto;padding:29px 35px 22px;flex:1}.footer{display:flex;justify-content:space-between;color:#a7afb2;font:8px 'DM Mono',monospace;letter-spacing:.8px;padding:12px 35px 15px;border-top:1px solid #e6e9e3}.footer b{font-weight:400;color:#77848a}.footer i{font-style:normal;color:#e78377;margin-left:5px}
.page-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:21px}.eyebrow{font:9px 'DM Mono',monospace;color:#8b969a;letter-spacing:1.45px;text-transform:uppercase;margin-bottom:8px}.page-heading h1{font-size:27px;line-height:1.1;letter-spacing:-1px;margin:0;font-weight:700}.page-heading p{margin:7px 0 0;color:#7a878e;font-size:12px}.btn{border:0;border-radius:3px;padding:11px 16px;font-weight:700;font-size:11px;display:inline-flex;align-items:center;gap:8px;transition:.16s}.btn-primary{background:var(--ink);color:#fff;box-shadow:3px 3px 0 #9cbe77}.btn-primary:hover{background:#274237;transform:translateY(-1px)}.btn-green{background:#dff4ce;color:#2c7849}.btn-ghost{background:#fff;border:1px solid var(--line);color:#55636d}.btn-small{padding:8px 11px;font-size:10px}.btn:disabled{opacity:.5;cursor:not-allowed}.panel{background:#fff;border:1px solid #e8ebe6;border-radius:5px;box-shadow:var(--shadow)}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(280px,.88fr);gap:17px}.hero-match{overflow:hidden;position:relative;background:#172b2c;color:white;min-height:270px;border-radius:5px;padding:20px 23px 17px;isolation:isolate}.hero-match:before{content:"";position:absolute;inset:0;z-index:-2;background:linear-gradient(90deg,#172b2c 4%,#193331d9 46%,#19333122 100%),linear-gradient(0deg,#172b2c 0%,transparent 65%),repeating-linear-gradient(90deg,#449563 0 12px,#3d895a 12px 24px)}.hero-match:after{content:"";position:absolute;width:43%;height:100%;right:0;top:0;z-index:-1;opacity:.38;background:repeating-linear-gradient(90deg,transparent 0 55px,#d1edc9 56px 58px,transparent 59px 112px),linear-gradient(transparent 49%,#e0f0dc 49.5% 50%,transparent 50.5%),linear-gradient(90deg,transparent 49%,#e0f0dc 49.5% 50%,transparent 50.5%);clip-path:inset(5% 0 5% 0)}.match-top{display:flex;justify-content:space-between;align-items:center}.live-tag{display:flex;align-items:center;gap:7px;font:9px 'DM Mono',monospace;letter-spacing:.9px;color:#c7e9bf}.live-tag i{width:6px;height:6px;background:#b1ec6f;border-radius:50%;box-shadow:0 0 8px #b1ec6f}.match-date{font:9px 'DM Mono',monospace;color:#bbccc4}.versus{display:flex;align-items:center;justify-content:space-between;max-width:570px;padding:22px 4px 13px}.team{display:flex;align-items:center;gap:12px}.team.away{flex-direction:row-reverse;text-align:right}.team-badge{width:53px;height:61px;clip-path:polygon(0 0,100% 0,100% 72%,50% 100%,0 72%);display:grid;place-items:center;font-size:25px;font-weight:700;text-shadow:1px 2px #17243288}.team-badge.home{background:#baf072;color:#19352b}.team-badge.away-badge{background:#f4c572;color:#66472b}.team-name{font-size:13px;font-weight:700}.team-name small{display:block;color:#bfd0c5;font-size:9px;font-weight:400;margin-top:5px}.versus-label{font:10px 'DM Mono',monospace;color:#c1d0c8;background:#ffffff17;padding:6px 9px;border-radius:2px}.match-info{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #ffffff25;padding-top:13px}.match-info small{color:#c1cec8;font-size:10px}.match-info b{color:#d5f8a7}.match-cta{background:var(--lime);color:#1c3426;border:0;border-radius:3px;padding:10px 13px;font-weight:700;font-size:10px}.match-cta:hover{background:#d8ff99}.match-cta span{font-size:15px;margin-left:7px}.hero-stats{position:absolute;right:19px;top:72px;display:flex;flex-direction:column;gap:10px;text-align:right;color:#c8d6cb;font:9px 'DM Mono',monospace}.hero-stats b{color:#d9f9b5;font-size:16px;display:block;margin-top:3px}.right-stack{display:grid;gap:14px}.club-status{padding:17px 18px}.section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:13px}.section-title h2{font-size:13px;margin:0;letter-spacing:-.3px}.section-title a,.text-link{color:#5d9b60;text-decoration:none;font-size:10px;font-weight:700;cursor:pointer}.rankline{display:flex;align-items:center;gap:10px}.rank-num{font:20px 'DM Mono',monospace;font-weight:500}.rank-meta{flex:1}.rank-meta b{font-size:10px;display:block}.rank-meta small{display:block;font-size:9px;color:#919ba0;margin-top:3px}.rank-change{color:#4b9d65;font:9px 'DM Mono',monospace}.rank-bar{height:5px;background:#f0f3ed;margin-top:13px;border-radius:9px;overflow:hidden}.rank-bar i{width:68%;height:100%;background:#82d199;display:block;border-radius:9px}.status-bottom{display:flex;justify-content:space-between;margin-top:8px;font-size:9px;color:#9aa3a6}.status-bottom b{color:#66747a}.economy-card{padding:15px 17px;display:flex;align-items:center;justify-content:space-between}.money-label{font-size:10px;color:#849097}.money-value{font:19px 'DM Mono',monospace;letter-spacing:-1px;margin-top:5px}.money-trend{font-size:9px;color:#4e9a63;margin-top:4px}.coin-icon{width:35px;height:35px;background:#e8f6dd;color:#7b9f4f;border-radius:50%;display:grid;place-items:center;font-size:19px}.lower-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(270px,.75fr);gap:17px;margin-top:17px}.panel-pad{padding:17px 18px}.table-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.table-head h2{font-size:13px;margin:0}.table-head small{font-size:9px;color:#9aa3a8}.standings{width:100%;border-collapse:collapse;font-size:10px}.standings th{text-align:left;color:#9aa3a8;font:8px 'DM Mono',monospace;letter-spacing:.6px;padding:8px 4px;border-bottom:1px solid #edf0ec}.standings td{padding:9px 4px;border-bottom:1px solid #f1f3f0;color:#687780}.standings tr:last-child td{border-bottom:0}.standings td:first-child{color:#a4adb0;width:21px;font:9px 'DM Mono',monospace}.standings td:nth-child(2){color:#374751;font-weight:600}.standings tr.my-team{background:#f4faee}.standings tr.my-team td:nth-child(2){color:#398551}.team-dot{width:17px;height:17px;display:inline-grid;place-items:center;border-radius:3px;color:#fff;font-size:8px;margin-right:6px;vertical-align:middle}.standings td:nth-child(n+3){text-align:center}.form-win{color:#58a86b}.form-loss{color:#da7474}.feed-panel{padding:17px}.feed-list{display:grid;gap:0}.feed-item{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid #f0f2ef}.feed-item:last-child{border:0}.feed-icon{width:29px;height:29px;flex-shrink:0;display:grid;place-items:center;border-radius:4px;background:#f1f8e9;color:#6b9c50;font-size:15px}.feed-icon.warning{background:#fff2e4;color:#d8914f}.feed-copy{font-size:10px;line-height:1.45;color:#627078}.feed-copy b{color:#34434c}.feed-copy small{display:block;color:#a3abad;font-size:8px;margin-top:3px}.feed-note{background:#f7f9f4;padding:9px;border-left:2px solid #b5de8a;color:#78847c;font-size:9px;line-height:1.4;margin-top:6px}
/* inner screens */
.toolbar{display:flex;gap:8px;align-items:center;margin-bottom:14px}.search-input,.select-input{border:1px solid var(--line);background:#fff;border-radius:3px;padding:9px 11px;font:10px 'Space Grotesk',sans-serif;color:#66747b;outline:none}.search-input:focus,.select-input:focus{border-color:#86c991}.search-input{width:200px}.push{margin-left:auto}.squad-layout{display:grid;grid-template-columns:minmax(0,1fr) 265px;gap:16px}.player-table-wrap{overflow:auto}.player-table{width:100%;border-collapse:collapse;min-width:570px}.player-table th{font:8px 'DM Mono',monospace;color:#9ba4a7;text-align:left;padding:12px;border-bottom:1px solid var(--line);letter-spacing:.5px}.player-table td{padding:11px 12px;border-bottom:1px solid #f0f1ee;font-size:10px}.player-table tr:last-child td{border:0}.player-row{cursor:pointer;transition:.15s}.player-row:hover,.player-row.selected{background:#f5faef}.player-ident{display:flex;align-items:center;gap:9px;min-width:140px}.player-face{width:29px;height:29px;border-radius:4px;background:#f1e2d3;display:grid;place-items:center;font-size:17px;overflow:hidden}.player-ident b{display:block;font-size:10px;color:#394750}.player-ident small{font-size:8px;color:#9ba4a7}.pos-tag{font:8px 'DM Mono',monospace;color:#76858a;background:#f3f5f2;padding:4px 5px;border-radius:2px}.rating{font:11px 'DM Mono',monospace;color:#438e60;font-weight:500}.morale{font-size:9px;color:#54a46c}.player-detail{padding:18px;position:sticky;top:15px;height:max-content}.detail-head{display:flex;align-items:center;gap:11px;padding-bottom:13px;border-bottom:1px solid var(--line)}.detail-face{width:48px;height:48px;font-size:26px;background:#f3e5d6}.detail-head h3{margin:0;font-size:14px}.detail-head small{color:#9ca5a7;font-size:9px}.detail-rating{margin-left:auto;font:18px 'DM Mono',monospace;color:#408d5e}.detail-section{margin-top:15px}.detail-label{font:8px 'DM Mono',monospace;color:#9ca5a7;letter-spacing:.8px;margin-bottom:8px}.stat-line{display:flex;justify-content:space-between;font-size:9px;margin:8px 0;color:#66747b}.stat-track{height:4px;background:#eef1eb;flex:1;margin:0 9px;align-self:center}.stat-track i{height:100%;background:#91d09a;display:block}.detail-meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.detail-meta div{background:#f7f8f5;padding:9px;border-radius:3px}.detail-meta small{display:block;font-size:8px;color:#99a2a3}.detail-meta b{display:block;font:10px 'DM Mono',monospace;margin-top:4px}.contract-box{display:flex;justify-content:space-between;align-items:center;margin-top:14px;padding-top:12px;border-top:1px solid var(--line);font-size:9px;color:#899397}.contract-box b{color:#41515a;font:10px 'DM Mono',monospace}.league-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.league-card{padding:19px}.league-banner{background:#182c32;color:#fff;padding:19px;border-radius:4px;position:relative;overflow:hidden;margin-bottom:17px}.league-banner:after{content:'✦';position:absolute;right:20px;top:-20px;font-size:100px;color:#c9f36d22}.league-banner small{font:8px 'DM Mono',monospace;color:#b5db9d;letter-spacing:1px}.league-banner h2{margin:7px 0 4px;font-size:21px}.league-banner p{margin:0;color:#b5c5bf;font-size:10px}.league-banner .league-prize{position:absolute;right:18px;bottom:15px;color:#d0f49c;font:11px 'DM Mono',monospace}.league-list{display:grid;gap:9px}.league-item{display:flex;align-items:center;gap:11px;padding:12px;background:#fff;border:1px solid var(--line);border-radius:4px}.league-emblem{width:34px;height:34px;display:grid;place-items:center;background:#f0f6e8;color:#668f45;border-radius:4px;font-size:17px}.league-item b{font-size:10px;display:block}.league-item small{font-size:8px;color:#929da0;display:block;margin-top:4px}.league-item .league-state{margin-left:auto;font:8px 'DM Mono',monospace;color:#579b65;background:#edf8e8;padding:5px 7px}.league-item.locked .league-emblem{background:#f3f3f0;color:#a1a7a5}.league-item.locked .league-state{color:#9ba3a2;background:#f3f4f1}.cashflow{padding:18px}.balance-box{background:#19302e;color:white;border-radius:5px;padding:19px;position:relative;overflow:hidden}.balance-box:after{content:'¢';position:absolute;right:18px;top:-17px;font-size:100px;color:#d4f19e18}.balance-box small{font:8px 'DM Mono',monospace;color:#b0c5b7;letter-spacing:1px}.balance-box h2{font:24px 'DM Mono',monospace;margin:10px 0 5px}.balance-box p{font-size:9px;color:#abd0ae;margin:0}.finance-row{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #edf0eb;font-size:10px}.finance-row:last-child{border:0}.finance-row span{color:#7d898e}.finance-row b{font:10px 'DM Mono',monospace;color:#47575c}.finance-row b.positive{color:#4d9d64}.finance-row b.negative{color:#d77668}.facility-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.facility-card{padding:17px;position:relative;overflow:hidden}.facility-icon{font-size:24px;width:46px;height:46px;background:#f1f8e9;border-radius:4px;display:grid;place-items:center;margin-bottom:14px}.facility-card h3{font-size:12px;margin:0 0 5px}.facility-card p{font-size:9px;line-height:1.5;color:#899499;min-height:28px;margin:0}.level-line{display:flex;justify-content:space-between;margin:13px 0 7px;font-size:9px;color:#77848a}.level-pips{display:flex;gap:4px}.level-pips i{height:4px;flex:1;background:#edf0ea;border-radius:3px}.level-pips i.on{background:#90d29a}.facility-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:14px;padding-top:12px;border-top:1px solid #eff1ed}.facility-bottom small{font:9px 'DM Mono',monospace;color:#828f93}.notice{font-size:10px;color:#728087;padding:13px;background:#f5f8f0;border-left:3px solid #b8df8e;margin-top:14px;line-height:1.5}.match-result{position:fixed;inset:0;background:#111b2ac9;z-index:10;display:grid;place-items:center;padding:20px}.result-card{background:#fff;width:min(460px,100%);border-radius:6px;padding:25px;text-align:center;box-shadow:0 20px 70px #0005}.result-card .eyebrow{color:#7da85b}.result-score{display:flex;justify-content:center;align-items:center;gap:24px;margin:20px 0}.result-team{font-size:10px;font-weight:700}.result-team span{display:block;font-size:25px;margin-bottom:5px}.score{font:35px 'DM Mono',monospace;color:#243634}.result-card p{font-size:11px;color:#7c898c;line-height:1.5}.result-events{margin:16px 0;text-align:left;background:#f7f8f4;border-radius:4px;padding:12px;font-size:10px;line-height:1.9;color:#59676d}.result-card .btn{margin-top:4px}.empty-state{text-align:center;padding:30px;color:#8b969a;font-size:11px}.toast{position:fixed;z-index:20;bottom:25px;left:50%;transform:translate(-50%,20px);background:#172a2c;color:#eaffdb;padding:11px 17px;font:10px 'DM Mono',monospace;border-radius:4px;box-shadow:0 8px 25px #14271e30;opacity:0;pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;z-index:12;background:#13202bc9;display:grid;place-items:center;padding:20px}.modal-card{width:min(410px,100%);background:#fff;border-radius:5px;padding:22px}.modal-card h2{font-size:18px;margin:0 0 9px}.modal-card p{font-size:11px;color:#7b878c;line-height:1.6}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}
