l economy-card"><div><div class="money-label">CAIXA DISPONÍVEL</div><div class="money-value">${money(state.cash)}</div><div class="money-trend">↗ &nbsp;${money(12500)} nesta rodada</div></div><div class="coin-icon">₡</div></section></div></div><div class="lower-grid"><section class="panel panel-pad"><div class="table-head"><h2>Classificação · Liga dos Cometas</h2><a class="text-link" data-page-link="leagues">VER LIGA COMPLETA →</a></div>${standingsTable()}</section><section class="panel feed-panel"><div class="table-head"><h2>Diário do clube</h2><small>ÚLTIMAS ATUALIZAÇÕES</small></div><div class="feed-list">${state.logs.slice(0,3).map((l,i)=>`<div class="feed-item"><div class="feed-icon ${i===1?'warning':''}">${l.icon}</div><div class="feed-copy">${l.text}<small>${l.time}</small></div></div>`).join('')}</div><div class="feed-note">💡 <b>Dica do treinador:</b> jogadores com energia alta rendem melhor. Gerencie o elenco antes da próxima rodada.</div></section></div>`}

