import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
try {
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  for (const [label, expected] of [['Elenco','Nosso elenco'], ['Ligas','Universo de ligas'], ['Finanças','Finanças do clube'], ['Instalações','Instalações']]) {
    await page.getByRole('button', { name: new RegExp(label) }).click();
    await page.getByRole('heading', { name: expected }).waitFor();
    console.log(`OK navegação: ${label}`);
  }
  await page.locator('[data-action="upgrade"]').first().click();
  await page.getByText('Melhoria concluída!').waitFor();
  console.log('OK melhoria de instalação');
  await page.getByRole('button', { name: 'Elenco' }).click();
  await page.getByRole('button', { name: /TREINO COLETIVO/ }).click();
  await page.getByText('Treino intenso! Quatro jogadores evoluíram.').waitFor();
  console.log('OK treino coletivo');
  await page.locator('[data-action="rest"]').click();
  console.log('OK descanso de jogador');
  await page.getByRole('button', { name: 'Painel' }).click();
  await page.getByRole('button', { name: /PRÓXIMA RODADA/ }).first().click();
  await page.getByRole('button', { name: 'CONTINUAR' }).waitFor();
  console.log('OK simulação de partida');
  await page.getByRole('button', { name: 'CONTINUAR' }).click();
  await page.locator('#appContent').waitFor();
  mkdirSync('/tmp/opencode', { recursive: true });
  await page.screenshot({ path: '/tmp/opencode/aurora-final.jpg', type: 'jpeg', quality: 72, fullPage: false });
  console.log('Screenshot: /tmp/opencode/aurora-final.jpg (1280x900 JPEG)');
  console.log(errors.length ? `Browser errors:\n${errors.join('\n')}` : 'No browser console/page errors.');
  if (errors.length) process.exitCode = 1;
} finally { await browser.close(); }

